import test from "node:test";
import assert from "node:assert/strict";
import {apply, planner} from "./replay.mjs";
import {Ledger} from "./common/ledger.mjs";
import {bookStudio, renewStudio} from "./services/studio.mjs";

const catalog = () => ({default: 5, studios: new Map([["orchid", 8], ["iris", 3]])});
const request = (id, units, extra = {}) => ({
  service: "studio", action: "book", id, units,
  tenant: "orchid", day: "2025-04-02", ...extra
});

test("Studio allocations are per tenant/day and Archive keeps the default", () => {
  const config = catalog();
  const dispatch = planner(config);
  assert.deepEqual(dispatch(request("one", 7)), {status: "booked", id: "one", remaining: 1});
  assert.deepEqual(dispatch(request("two", 2)), {status: "full", id: "two", remaining: 1});
  assert.equal(dispatch(request("two", 1)).status, "booked");
  assert.equal(dispatch(request("other-day", 8, {day: "2025-04-03"})).status, "booked");
  assert.equal(dispatch(request("iris-full", 4, {tenant: "iris"})).status, "full");
  assert.equal(dispatch(request("iris-ok", 3, {tenant: "iris"})).remaining, 0);
  assert.equal(dispatch(request("unlisted-full", 6, {tenant: "lily"})).status, "full");
  assert.equal(dispatch(request("unlisted-ok", 5, {tenant: "lily"})).status, "booked");
  assert.equal(dispatch(request("archive-full", 6, {service: "archive"})).status, "full");
  assert.equal(dispatch(request("archive-ok", 5, {service: "archive"})).remaining, 0);
  assert.equal(config.default, 5);
  assert.deepEqual([...config.studios], [["orchid", 8], ["iris", 3]]);
});

test("replays, conflicts, cancellations and imported usage retain ledger semantics", () => {
  const dispatch = planner(catalog());
  const original = request("original", 7);
  dispatch(original);
  dispatch(request("last", 1));
  assert.deepEqual(dispatch(original), {status: "replay", id: "original"});
  assert.equal(dispatch({...original, units: 6}).status, "conflict");
  assert.equal(dispatch({service: "studio", action: "cancel", id: "original"}).status, "cancelled");
  assert.equal(dispatch(original).status, "cancelled");
  assert.equal(dispatch({service: "studio", action: "cancel", id: "original"}).status, "replay");
  assert.equal(dispatch(request("replacement", 7)).remaining, 0);
  assert.deepEqual(dispatch({service: "studio", action: "usage", tenant: "orchid", day: original.day}), {units: 8});
  assert.equal(dispatch(request("backfill", 10, {action: "import", day: "2025-04-04"})).status, "imported");
  assert.deepEqual(dispatch(request("over-import", 1, {day: "2025-04-04"})), {status: "full", id: "over-import", remaining: 0});
  const summary = dispatch({service: "studio", action: "summary"});
  assert.equal(summary.events.length, 5);
  assert.equal(summary.occupied.some(row => row.id === "original"), false);
});

test("renewals use inherited tenant quotas, target-day usage and existing replay rules", () => {
  const dispatch = planner(catalog());
  dispatch(request("previous", 7));
  const renewal = {service: "studio", action: "renew", previous: "previous", id: "next", day: "2025-05-02"};
  assert.equal(dispatch(renewal).remaining, 1);
  dispatch(request("next-extra", 1, {day: renewal.day}));
  assert.equal(dispatch(renewal).status, "replay");
  assert.equal(dispatch({...renewal, units: 6}).status, "conflict");
  assert.equal(dispatch({...renewal, id: "too-many"}).remaining, 0);
  dispatch({service: "studio", action: "cancel", id: "next"});
  assert.equal(dispatch(renewal).status, "cancelled");
  assert.equal(dispatch({...renewal, id: "replacement", units: 7}).status, "booked");
  dispatch({service: "studio", action: "cancel", id: "previous"});
  assert.deepEqual(dispatch({...renewal, id: "missing"}), {status: "missing", id: "previous"});

  for (const [tenant, cap] of [["iris", 3], ["lily", 5]]) {
    dispatch(request(tenant, 1, {tenant}));
    const next = {...renewal, previous: tenant, id: tenant + "-next", units: cap + 1};
    assert.equal(dispatch(next).status, "full");
    assert.equal(dispatch({...next, units: cap}).remaining, 0);
  }
  dispatch(request("archive", 5, {service: "archive"}));
  assert.equal(dispatch({...renewal, service: "archive", previous: "archive", id: "archive-next", units: 6}).status, "full");
  assert.equal(apply(dispatch, request("invalid", 0)).status, "invalid");
});

test("Studio adapters work directly with the reservation kit", () => {
