  assert.equal(renewStudio(ledger, {previous: "direct", id: "renewed", day: "2025-05-02"}).status, "booked");
  assert.equal(ledger.catalog.default, 5);
  assert.equal(ledger.usage("orchid", "2025-05-02"), 8);
});
